const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const moroto = ee.Geometry.Point(34.66, 2.53);
  const aoi = moroto.buffer(40000); // 40 km radius
  const scale = 3000; // Use a coarse scale to avoid timeouts over large areas and long time periods.

  // 2. Data Acquisition & Processing Functions
  // Cloud mask function for Landsat 4/5/7 Collection 2
  function maskL457(image) {
    const qa = image.select('QA_PIXEL');
    const cloud = qa.bitwiseAnd(1 << 5).or(qa.bitwiseAnd(1 << 7));
    return image.updateMask(cloud.not());
  }

  // Cloud mask function for Landsat 8/9 Collection 2
  function maskL89(image) {
    const qa = image.select('QA_PIXEL');
    const cloud = qa.bitwiseAnd(1 << 3).or(qa.bitwiseAnd(1 << 4));
    return image.updateMask(cloud.not());
  }

  // NDVI calculation function (handles different band names)
  function addNDVI(image) {
    // Select bands based on a list of potential band names for each sensor
    const nir = image.select(['SR_B4', 'SR_B5'], ['NIR']).select('NIR');
    const red = image.select(['SR_B3', 'SR_B4'], ['RED']).select('RED');
    // Apply a scaling factor common to Landsat C2 SR products
    const scaledImage = image.addBands(nir.multiply(0.0000275).add(-0.2)).addBands(red.multiply(0.0000275).add(-0.2));
    return scaledImage.normalizedDifference(['NIR', 'RED']).rename('NDVI');
  }

  // --- Historical Period (1991-2010) ---
  const historicalStart = '1991-08-01';
  const historicalEnd = '2010-08-31';

  const l5 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
               .filterBounds(aoi)
               .filter(ee.Filter.calendarRange(8, 8, 'month'));
  const l7 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
               .filterBounds(aoi)
               .filter(ee.Filter.calendarRange(8, 8, 'month'));

  const historicalCol = ee.ImageCollection(
      l5.filter(ee.Filter.date(historicalStart, '1999-12-31')).map(maskL457)
        .merge(l7.filter(ee.Filter.date('2000-01-01', historicalEnd)).map(maskL457))
  );

  if (historicalCol.size().getInfo() === 0) {
      console.log("No images found for historical period (1991-2010).");
      console.log('B'); // Logically, 2023 cannot be lower than a non-existent value.
      return;
  }

  const historicalNDVI = historicalCol.map(addNDVI).mean();
  const historicalMean = historicalNDVI.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: aoi,
      scale: scale,
      maxPixels: 1e9
  }).get('NDVI');

  const historicalPixelCount = historicalNDVI.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: aoi,
      scale: scale,
      maxPixels: 1e9
  }).get('NDVI');

  const historicalMeanVal = historicalMean.getInfo();
  if (historicalMeanVal === null || historicalPixelCount.getInfo() === 0) {
      console.log("Historical Period (1991-2010): No valid pixels after masking.");
      console.log('C2');
      return;
  }
  console.log(`Historical NDVI (1991-2010): ${historicalMeanVal.toFixed(4)}`);

  // --- Recent Period (2023) ---
  const recentStart = '2023-08-01';
  const recentEnd = '2023-08-31';

  let recentCol = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
                      .filterBounds(aoi)
                      .filterDate(recentStart, recentEnd)
                      .map(maskL89);

  if (recentCol.size().getInfo() === 0) {
      recentCol = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
                     .filterBounds(aoi)
                     .filterDate(recentStart, recentEnd)
                     .map(maskL89);
  }

  if (recentCol.size().getInfo() === 0) {
      console.log("No images found for recent period (August 2023).");
      console.log('C1');
      return;
  }

  const recentNDVI = recentCol.map(addNDVI).mean();
  const recentMean = recentNDVI.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: aoi,
      scale: scale,
      maxPixels: 1e9
  }).get('NDVI');

  const recentPixelCount = recentNDVI.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: aoi,
      scale: scale,
      maxPixels: 1e9
  }).get('NDVI');

  const recentMeanVal = recentMean.getInfo();
  if (recentMeanVal === null || recentPixelCount.getInfo() === 0) {
      console.log("Recent Period (Aug 2023): No valid pixels after masking.");
      console.log('C2');
      return;
  }
  console.log(`Recent NDVI (Aug 2023): ${recentMeanVal.toFixed(4)}`);

  // 5. Validation & Final Answer
  if (recentMeanVal < historicalMeanVal) {
      console.log('A');
  } else {
      console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error('An error occurred:', err);
    console.log('D');
});
